create extension if not exists pgcrypto;

create table public.sc_albums (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 255),
  description text,
  release_year integer check (release_year between 1900 and 2200),
  cover_path text,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.sc_lyrics (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  album_id uuid references public.sc_albums(id) on delete set null,
  title text not null check (char_length(title) between 1 and 255),
  style_prompt text,
  lyrics text,
  notes text,
  cover_path text,
  status text not null default 'draft' check (status in ('draft','complete')),
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.sc_songs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  album_id uuid references public.sc_albums(id) on delete set null,
  source_lyric_id uuid references public.sc_lyrics(id) on delete set null,
  title text not null check (char_length(title) between 1 and 255),
  style_prompt text,
  lyrics text,
  notes text,
  cover_path text,
  completed_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.sc_audio_versions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  song_id uuid not null references public.sc_songs(id) on delete cascade,
  label text not null check (char_length(label) between 1 and 255),
  original_file_name text not null,
  storage_path text not null,
  tagged_storage_path text,
  mime_type text not null default 'audio/mpeg',
  byte_size bigint not null default 0 check (byte_size >= 0),
  rating smallint not null default 0 check (rating between 0 and 5),
  is_primary boolean not null default false,
  is_final boolean not null default false,
  id3_title text,
  id3_artist text default 'Temney',
  id3_album text,
  id3_track_number text,
  id3_year text,
  id3_genre text,
  id3_comment text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.sc_rhyme_words (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  word text not null check (char_length(word) between 2 and 100),
  created_at timestamptz not null default now(),
  unique(user_id, word)
);

create index sc_albums_user_idx on public.sc_albums(user_id);
create index sc_lyrics_user_idx on public.sc_lyrics(user_id);
create index sc_songs_user_idx on public.sc_songs(user_id);
create index sc_versions_song_idx on public.sc_audio_versions(song_id);

alter table public.sc_albums enable row level security;
alter table public.sc_lyrics enable row level security;
alter table public.sc_songs enable row level security;
alter table public.sc_audio_versions enable row level security;
alter table public.sc_rhyme_words enable row level security;

create policy sc_albums_owner on public.sc_albums for all using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy sc_lyrics_owner on public.sc_lyrics for all using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy sc_songs_owner on public.sc_songs for all using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy sc_versions_owner on public.sc_audio_versions for all using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy sc_rhyme_words_owner on public.sc_rhyme_words for all using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

insert into storage.buckets (id, name, public) values ('songcraft', 'songcraft', false);
create policy sc_storage_owner_select on storage.objects for select using (bucket_id = 'songcraft' and (storage.foldername(name))[1] = (select auth.uid()::text));
create policy sc_storage_owner_insert on storage.objects for insert with check (bucket_id = 'songcraft' and (storage.foldername(name))[1] = (select auth.uid()::text));
create policy sc_storage_owner_update on storage.objects for update using (bucket_id = 'songcraft' and (storage.foldername(name))[1] = (select auth.uid()::text)) with check (bucket_id = 'songcraft' and (storage.foldername(name))[1] = (select auth.uid()::text));
create policy sc_storage_owner_delete on storage.objects for delete using (bucket_id = 'songcraft' and (storage.foldername(name))[1] = (select auth.uid()::text));
